// Fisher-Yates shuffle (Durstenfeld's version) over a seeded generator.
List<T> shuffle<T>(List<T> items, int Function(int max) next) {
  final out = [...items];
  for (var i = out.length - 1; i > 0; i--) {
    final j = next(i + 1);
    final t = out[i];
    out[i] = out[j];
    out[j] = t;
  }
  return out;
}
